import { render, screen } from '@testing-library/react'
import HomePage from '@/app/page'

describe('Home — accounts overview', () => {
  it('AC1: greets Alex and lists exactly three named accounts', () => {
    render(<HomePage />)
    expect(screen.getByText(/Hello,\s*Alex/)).toBeInTheDocument()
    expect(screen.getByText('Everyday')).toBeInTheDocument()
    expect(screen.getByText('Savings')).toBeInTheDocument()
    expect(screen.getByText('Credit card')).toBeInTheDocument()
  })

  it('AC3: shows the Savings interest rate as "4.50% p.a."', () => {
    render(<HomePage />)
    expect(screen.getByText('4.50% p.a.')).toBeInTheDocument()
  })

  it('AC4: shows credit card owing and limit, both formatted in AUD', () => {
    render(<HomePage />)
    expect(screen.getByText(/owing/i)).toBeInTheDocument()
    expect(screen.getByText(/limit/i)).toBeInTheDocument()
    const amounts = screen.getAllByText(/\$[\d,]+\.\d{2}/)
    // three account balances + owing + limit = 5 formatted amounts minimum
    expect(amounts.length).toBeGreaterThanOrEqual(4)
  })

  it('AC5: links each account to its slug-based detail page', () => {
    render(<HomePage />)
    expect(screen.getByRole('link', { name: /Everyday/i })).toHaveAttribute('href', '/accounts/everyday')
    expect(screen.getByRole('link', { name: /Savings/i })).toHaveAttribute('href', '/accounts/savings')
    expect(screen.getByRole('link', { name: /Credit card/i })).toHaveAttribute('href', '/accounts/credit-card')
  })

  it('AC2 + AC12: shows masked account numbers and never leaks a full number', () => {
    render(<HomePage />)
    const textContent = document.body.textContent ?? ''
    // At least one masked number visible (mask chars then four digits)
    expect(textContent).toMatch(/(?:•|\u2022|\*|·|\.){2,}\s?\d{4}/)
    // No run of six-or-more consecutive digits anywhere
    expect(textContent).not.toMatch(/\d{6,}/)
  })
})

contracts.definition:
data/accounts.json — top-level array of Account.

type Account = {
  id: 'everyday' | 'savings' | 'credit-card';
  name: 'Everyday' | 'Savings' | 'Credit card';
  masked_number: string;                  // e.g. '•••• 4821'; last four digits only
  balance: number;                        // AUD; for credit-card, the amount currently owing
  interest_rate?: number;                 // percent p.a., savings only (e.g. 4.5)
  credit_limit?: number;                  // AUD, credit-card only (e.g. 10000)
  transactions: Transaction[];
};

type Transaction = {
  date: string;                           // ISO 8601 date, YYYY-MM-DD
  description: string;                    // customer-facing merchant/description; no PAY-1234-style refs (PCP-02)
  amount: number;                         // signed; positive = money in, negative = money out
  balance_after: number;                  // AUD; for credit-card, the amount owing after the txn
};

Invariant: for every account, account.balance === transactions_sorted_desc[0].balance_after.
